CREATE OR REPLACE FUNCTION public.coach_athlete_movement_observations(_athlete uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public._coach_training_access(_athlete) THEN RAISE EXCEPTION 'Player connection required' USING ERRCODE='42501'; END IF; IF auth.uid() <> _athlete AND NOT public.resolve_recruiting_scope(_athlete,'health') THEN RETURN jsonb_build_object('shared',false); END IF; SELECT jsonb_build_object('shared',true,'movement_screen',movement_screen,'updated_at',updated_at,'recorded_by_label',recorded_by_label) INTO result FROM public.initial_assessments WHERE user_id=_athlete; RETURN COALESCE(result,jsonb_build_object('shared',true,'movement_screen',null)); END; $$; REVOKE ALL ON FUNCTION public.coach_athlete_movement_observations(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.coach_athlete_movement_observations(uuid) TO authenticated, service_role; COMMENT ON FUNCTION public.coach_athlete_movement_observations(uuid) IS 'Connected assigned training viewers plus current health consent only; observations never diagnosis or dose authority.';